/**
 * The answer of a player.
 */
public struct PhomuAnswer {
    /**
     * The identifier of the mode the answer belongs to.
     */
    public var mode: String
    /**
     * The slot the player chose — the Timeline mode.
     */
    public var timelineSlot: UInt32?
    /**
     * The hint level that was reached — the Hint-Master mode.
     */
    public var hintLevel: UInt32?
    /**
     * What the pilot knew: `both`, `artist`, `title` or `none` — the
     * Hint-Master mode.
     */
    public var knewWhat: String?
    /**
     * Whether the picked line was the invented one — the Lyrics mode.
     */
    public var pickedFake: Bool?
    /**
     * Whether the player recognised the song — the bonus round of the Lyrics
     * mode.
     */
    public var claimed: Bool?
    /**
     * The mood the player picked — the Vibe-Check mode.
     */
    public var mood: String?
    /**
     * Whether the cheat was used — the Vibe-Check mode.
     */
    public var cheatUsed: Bool?
    /**
     * Whether the player guessed "one-hit wonder" — the Survivor mode.
     */
    public var guessedOneHit: Bool?
    /**
     * The number of hints that were used — the Cover Confusion mode.
     */
    public var hintsUsed: UInt32?
    /**
     * The artist the player picked — the Cover Confusion mode.
     */
    public var pickedArtist: String?
    /**
     * The self-assessment — the Cover Confusion mode.
     */
    public var selfAssess: Bool?
    /**
     * Whether the player answered "cover" — the variation of the Cover
     * Confusion mode.
     */
    public var guessCover: Bool?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * The identifier of the mode the answer belongs to.
         */mode: String, 
        /**
         * The slot the player chose — the Timeline mode.
         */timelineSlot: UInt32?, 
        /**
         * The hint level that was reached — the Hint-Master mode.
         */hintLevel: UInt32?, 
        /**
         * What the pilot knew: `both`, `artist`, `title` or `none` — the
         * Hint-Master mode.
         */knewWhat: String?, 
        /**
         * Whether the picked line was the invented one — the Lyrics mode.
         */pickedFake: Bool?, 
        /**
         * Whether the player recognised the song — the bonus round of the Lyrics
         * mode.
         */claimed: Bool?, 
        /**
         * The mood the player picked — the Vibe-Check mode.
         */mood: String?, 
        /**
         * Whether the cheat was used — the Vibe-Check mode.
         */cheatUsed: Bool?, 
        /**
         * Whether the player guessed "one-hit wonder" — the Survivor mode.
         */guessedOneHit: Bool?, 
        /**
         * The number of hints that were used — the Cover Confusion mode.
         */hintsUsed: UInt32?, 
        /**
         * The artist the player picked — the Cover Confusion mode.
         */pickedArtist: String?, 
        /**
         * The self-assessment — the Cover Confusion mode.
         */selfAssess: Bool?, 
        /**
         * Whether the player answered "cover" — the variation of the Cover
         * Confusion mode.
         */guessCover: Bool?) {
        self.mode = mode
        self.timelineSlot = timelineSlot
        self.hintLevel = hintLevel
        self.knewWhat = knewWhat
        self.pickedFake = pickedFake
        self.claimed = claimed
        self.mood = mood
        self.cheatUsed = cheatUsed
        self.guessedOneHit = guessedOneHit
        self.hintsUsed = hintsUsed
        self.pickedArtist = pickedArtist
        self.selfAssess = selfAssess
        self.guessCover = guessCover
    }
}

