extension PhomuAnswer: Equatable, Hashable {
    public static func ==(lhs: PhomuAnswer, rhs: PhomuAnswer) -> Bool {
        if lhs.mode != rhs.mode {
            return false
        }
        if lhs.timelineSlot != rhs.timelineSlot {
            return false
        }
        if lhs.hintLevel != rhs.hintLevel {
            return false
        }
        if lhs.knewWhat != rhs.knewWhat {
            return false
        }
        if lhs.pickedFake != rhs.pickedFake {
            return false
        }
        if lhs.claimed != rhs.claimed {
            return false
        }
        if lhs.mood != rhs.mood {
            return false
        }
        if lhs.cheatUsed != rhs.cheatUsed {
            return false
        }
        if lhs.guessedOneHit != rhs.guessedOneHit {
            return false
        }
        if lhs.hintsUsed != rhs.hintsUsed {
            return false
        }
        if lhs.pickedArtist != rhs.pickedArtist {
            return false
        }
        if lhs.selfAssess != rhs.selfAssess {
            return false
        }
        if lhs.guessCover != rhs.guessCover {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(mode)
        hasher.combine(timelineSlot)
        hasher.combine(hintLevel)
        hasher.combine(knewWhat)
        hasher.combine(pickedFake)
        hasher.combine(claimed)
        hasher.combine(mood)
        hasher.combine(cheatUsed)
        hasher.combine(guessedOneHit)
        hasher.combine(hintsUsed)
        hasher.combine(pickedArtist)
        hasher.combine(selfAssess)
        hasher.combine(guessCover)
    }
}



