        /**
         * The identifiers of the packs the session draws from.
         */selectedPacks: [String], 
        /**
         * How the players are grouped: `individual`, `fixed` or `shifting`.
         */teamMode: String, 
        /**
         * How the game is played: `pass-the-phone` or `multi-device`.
         */deviceMode: String, 
        /**
         * What ends the game: `points`, `rounds` or `time`.
         */endingCondition: String, 
        /**
         * The score that ends the game.
         */targetPoints: Int64, 
        /**
         * The number of rounds per player or per team.
         */targetRounds: UInt32, 
        /**
         * The number of minutes the game lasts.
         */targetTimeMinutes: UInt32, 
        /**
         * The upper bound of a question round, in seconds.
         */timeLimitSeconds: UInt32?, 
        /**
         * The difficulty the songs have to have: `all`, `easy`, `medium` or
         * `hard`.
         */difficulty: String, 
        /**
         * The maximum number of points in the Timeline mode.
         */timelineMaxPoints: UInt32, 
        /**
         * Whether the time decay is active.
         */timeDecayEnabled: Bool, 
        /**
         * The number of seconds after which the first decay step applies.
         */timeDecayGraceSeconds: UInt32, 
        /**
         * The width of one decay step, in seconds.
         */timeDecayStepSeconds: UInt32, 
        /**
         * The number of points deducted per decay step.
         */timeDecayStepPoints: UInt32, 
        /**
         * The lower bound of the points of a correct answer.
         */minPointsPerCorrect: UInt32, 
        /**
         * Who may perform the override actions: `host`, `co-host` or
         * `majority`.
         */overrideGovernance: String, 
        /**
         * How the hints are published: `auto-publish` or `manual-review`.
         */hintReleasePolicy: String, 
        /**
         * What happens when the hint service is blocked: `queue-retry` or
         * `fail-fast`.
         */aiQueueStrategy: String, 
        /**
         * Whether the chips mechanic is active.
         */chipsEnabled: Bool, 
        /**
         * Whether the cheat buttons are hidden.
         */noCheatMode: Bool, 
        /**
         * Whether only songs with a physical card may be drawn.
         */onlyQrCompatible: Bool, 
        /**
         * Who leaves the game: `none` or `below-score:<threshold>`.
         */eliminationRule: String, 
        /**
         * The provider the players prefer.
         */preferredMusicProvider: String) {
        self.selectedModes = selectedModes
        self.selectedPacks = selectedPacks
        self.teamMode = teamMode
        self.deviceMode = deviceMode
        self.endingCondition = endingCondition
        self.targetPoints = targetPoints
        self.targetRounds = targetRounds
        self.targetTimeMinutes = targetTimeMinutes
        self.timeLimitSeconds = timeLimitSeconds
        self.difficulty = difficulty
        self.timelineMaxPoints = timelineMaxPoints
        self.timeDecayEnabled = timeDecayEnabled
        self.timeDecayGraceSeconds = timeDecayGraceSeconds
        self.timeDecayStepSeconds = timeDecayStepSeconds
        self.timeDecayStepPoints = timeDecayStepPoints
        self.minPointsPerCorrect = minPointsPerCorrect
        self.overrideGovernance = overrideGovernance
        self.hintReleasePolicy = hintReleasePolicy
        self.aiQueueStrategy = aiQueueStrategy
        self.chipsEnabled = chipsEnabled
        self.noCheatMode = noCheatMode
        self.onlyQrCompatible = onlyQrCompatible
        self.eliminationRule = eliminationRule
        self.preferredMusicProvider = preferredMusicProvider
    }
}

