#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypePhomuRoundView: FfiConverterRustBuffer {
    typealias SwiftType = PhomuRoundView

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PhomuRoundView {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .drawing(roundNumber: try FfiConverterUInt32.read(from: &buf), mode: try FfiConverterString.read(from: &buf), autoDraw: try FfiConverterBool.read(from: &buf)
        )
        
        case 2: return .question(roundNumber: try FfiConverterUInt32.read(from: &buf), mode: try FfiConverterString.read(from: &buf), hints: try FfiConverterSequenceString.read(from: &buf), options: try FfiConverterSequenceString.read(from: &buf), pointsPossible: try FfiConverterUInt32.read(from: &buf), answersLocked: try FfiConverterBool.read(from: &buf)
        )
        
        case 3: return .scoring(roundNumber: try FfiConverterUInt32.read(from: &buf), mode: try FfiConverterString.read(from: &buf), winnerId: try FfiConverterOptionString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: PhomuRoundView, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .drawing(roundNumber,mode,autoDraw):
            writeInt(&buf, Int32(1))
            FfiConverterUInt32.write(roundNumber, into: &buf)
            FfiConverterString.write(mode, into: &buf)
            FfiConverterBool.write(autoDraw, into: &buf)
            
        
        case let .question(roundNumber,mode,hints,options,pointsPossible,answersLocked):
            writeInt(&buf, Int32(2))
            FfiConverterUInt32.write(roundNumber, into: &buf)
            FfiConverterString.write(mode, into: &buf)
            FfiConverterSequenceString.write(hints, into: &buf)
            FfiConverterSequenceString.write(options, into: &buf)
            FfiConverterUInt32.write(pointsPossible, into: &buf)
            FfiConverterBool.write(answersLocked, into: &buf)
            
        
        case let .scoring(roundNumber,mode,winnerId):
            writeInt(&buf, Int32(3))
            FfiConverterUInt32.write(roundNumber, into: &buf)
            FfiConverterString.write(mode, into: &buf)
            FfiConverterOptionString.write(winnerId, into: &buf)
            
        }
    }
}


