#if swift(>=5.8)
@_documentation(visibility: private)
#endif
fileprivate struct FfiConverterDictionaryStringString: FfiConverterRustBuffer {
    public static func write(_ value: [String: String], into buf: inout [UInt8]) {
        let len = Int32(value.count)
        writeInt(&buf, len)
        for (key, value) in value {
            FfiConverterString.write(key, into: &buf)
            FfiConverterString.write(value, into: &buf)
        }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> [String: String] {
        let len: Int32 = try readInt(&buf)
        var dict = [String: String]()
        dict.reserveCapacity(Int(len))
        for _ in 0..<len {
            let key = try FfiConverterString.read(from: &buf)
            let value = try FfiConverterString.read(from: &buf)
            dict[key] = value
        }
        return dict
    }
}
/**
 * Whether the version of the base lies inside the bracket of a shell.
 *
 * WHY the check is closed: a shell that runs against a base it was not
 * written for must stop at start-up and not in the middle of a round
 * (docs/design/BUILD-CONTRACT.md § 3.2).
 */
public func phomuAbiAccepts(minMajor: UInt16, minMinor: UInt16, minPatch: UInt16, maxMajor: UInt16, maxMinor: UInt16, maxPatch: UInt16) -> Bool  {
    return try!  FfiConverterBool.lift(try! rustCall() {
    uniffi_phomu_ffi_fn_func_phomu_abi_accepts(
        FfiConverterUInt16.lower(minMajor),
        FfiConverterUInt16.lower(minMinor),
        FfiConverterUInt16.lower(minPatch),
        FfiConverterUInt16.lower(maxMajor),
        FfiConverterUInt16.lower(maxMinor),
        FfiConverterUInt16.lower(maxPatch),$0
    )
})
}
