private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 29
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_phomu_ffi_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_phomu_ffi_checksum_func_phomu_abi_accepts() != 31963) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_phomu_ffi_checksum_func_phomu_abi_version() != 1317) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_phomu_ffi_checksum_func_phomu_abi_versions() != 25775) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_phomu_ffi_checksum_func_phomu_capabilities() != 45928) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_phomu_ffi_checksum_func_phomu_catalog_open() != 4682) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_phomu_ffi_checksum_func_phomu_catalog_packs() != 14286) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_phomu_ffi_checksum_func_phomu_catalog_songs() != 41888) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_phomu_ffi_checksum_func_phomu_media_plan() != 26191) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_phomu_ffi_checksum_func_phomu_message_key() != 12864) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_phomu_ffi_checksum_func_phomu_session_answer() != 45823) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_phomu_ffi_checksum_func_phomu_session_draw() != 21863) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_phomu_ffi_checksum_func_phomu_session_end() != 33620) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_phomu_ffi_checksum_func_phomu_session_new() != 25222) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_phomu_ffi_checksum_func_phomu_session_next_round() != 59417) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_phomu_ffi_checksum_func_phomu_session_reveal() != 63488) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_phomu_ffi_checksum_func_phomu_session_snapshot() != 20147) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_phomu_ffi_checksum_func_phomu_session_start() != 55823) {
        return InitializationResult.apiChecksumMismatch
    }

    return InitializationResult.ok
}()

// Make the ensure init function public so that other modules which have external type references to
// our types can call it.
public func uniffiEnsurePhomuFfiInitialized() {
    switch initializationResult {
    case .ok:
        break
    case .contractVersionMismatch:
        fatalError("UniFFI contract version mismatch: try cleaning and rebuilding your project")
    case .apiChecksumMismatch:
        fatalError("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
}

